    @Test
    void recusaComCodigoDeErroQuandoModalidadeNaoExiste() throws Exception {
        mvc.perform(post("/checkout/resumo")
                        .contentType("application/json")
                        .content("""
                                {
                                  "itens": [{"nome": "Meia", "precoUnitario": 19.90, "quantidade": 1, "pesoKg": 0.10}],
